// calculadora.mjs — funções para testar
export function dividir(a, b) {
  if (b === 0) throw new Error('não pode dividir por zero');
  return a / b;
}

export async function buscarUsuario(id) {
  if (id <= 0) throw new Error('id inválido');
  return { id, nome: 'Ana' };
}

// calculadora.test.mjs — os três tipos de caso
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dividir, buscarUsuario } from './calculadora.mjs';

test('caso normal: divisão comum', () => {
  assert.strictEqual(dividir(10, 2), 5);
});

test('caso de erro: dividir por zero lança erro', () => {
  assert.throws(() => dividir(1, 0), /zero/); // espera um erro que mencione "zero"
});

test('caso de erro assíncrono: id inválido rejeita a Promise', async () => {
  await assert.rejects(buscarUsuario(0), /inválido/);
});

// validarEmail.mjs — a função de validação
export function validarEmail(email) {
  const temArroba = email.includes('@');       // precisa ter @
  const depois = email.split('@')[1] || '';    // o que vem depois do @
  const temPontoDepois = depois.includes('.'); // e um ponto depois
  return temArroba && temPontoDepois;          // só é válido com os dois
}

// validarEmail.test.mjs — o checklist de testes
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validarEmail } from './validarEmail.mjs';

test('caso normal: e-mail comum é aceito', () => {
  assert.strictEqual(validarEmail('ana@exemplo.com'), true);
});

test('caso limite: sem ponto depois do @ é rejeitado', () => {
  assert.strictEqual(validarEmail('ana@exemplo'), false);
});

test('caso de erro: sem @ é rejeitado', () => {
  assert.strictEqual(validarEmail('anaexemplo.com'), false);
});
